insert into public.items (id, category_id, slot, value, name, description, rarity_id, currency_id, price, stackable, max_quantity, sellable, purchasable, gift, grant_type, event_id, color) values ('hx_hoodie', 'char', 'shirt', '"hx_hoodie"'::jsonb, 'Moletom do Código', 'Moletom azul-marinho com capuz e linhas de código turquesa descendo pelo rosto.', 'common', 'gold', 45, false, null, true, true, false, 'shop', null, null) on conflict (id) do update set category_id = excluded.category_id, slot = excluded.slot, value = excluded.value, name = excluded.name, description = excluded.description, rarity_id = excluded.rarity_id, price = excluded.price, stackable = excluded.stackable, max_quantity = excluded.max_quantity, sellable = excluded.sellable, purchasable = excluded.purchasable, gift = excluded.gift, grant_type = excluded.grant_type, event_id = excluded.event_id, color = excluded.color, active = true;
