-- 2) the retired items and what was paid for each
create temporary table retired_items (item_id text primary key, price integer not null) on commit drop;
insert into retired_items (item_id, price) values ('rack_clean', 15), ('rack_corp', 15), ('rack_industrial', 30), ('rack_gamer', 60), ('rack_cyber', 120), ('rack_gold', 250), ('rack_launch', 90), ('srv_clean', 15), ('srv_carbon', 30), ('srv_neon', 55), ('srv_cyber', 110), ('srv_gold', 230), ('sw_clean', 15), ('sw_industrial', 30), ('sw_gamer', 55), ('sw_cyber', 110), ('sto_clean', 15), ('sto_industrial', 30), ('sto_cyber', 110), ('sto_gold', 230), ('acc_fans', 25), ('acc_beacon', 25), ('acc_plate', 45), ('acc_stickers', 10), ('led_cyan', 12), ('led_magenta', 22), ('led_amber', 22), ('led_rgb', 50), ('led_gold', 100), ('shirt_polo', 12), ('shirt_striped', 12), ('shirt_flannel', 25), ('shirt_jacket', 45), ('shirt_jersey', 45), ('shirt_launch', 40), ('costume_hero', 120), ('costume_ceo', 70), ('costume_hacker', 100), ('costume_tech', 70), ('costume_mage', 150), ('costume_chef', 60), ('costume_king', 300), ('pants_jeans', 12), ('pants_cargo', 22), ('pants_baggy', 22), ('pants_joggers', 40), ('pants_shorts', 10), ('hair_undercut', 12), ('hair_spiky', 22), ('hair_braids', 40), ('hair_mohawk', 90), ('hat_snapback', 12), ('hat_backcap', 20), ('hat_bucket', 40), ('hat_crown', 250), ('hat_launch', 0), ('acc_shades', 10), ('acc_scarf', 10), ('acc_backpack', 20), ('acc_chain', 90), ('pal_pastel', 20), ('pal_neon', 40), ('pal_gold', 100);

-- 3) who is wearing a retired skin (equipped, or only on the avatar) gets the first new skin
create temporary table skin_swap (user_id uuid primary key) on commit drop;
insert into skin_swap (user_id)
  select distinct e.user_id from public.equipped_items e join retired_items r on r.item_id = e.item_id where e.slot = 'shirt'
  on conflict do nothing;
insert into skin_swap (user_id)
  select p.id from public.profiles p
  where p.avatar ->> 'outfit' in ('polo', 'striped', 'flannel', 'jacket', 'jersey', 'launch', 'hero', 'ceo', 'hacker', 'tech', 'mage', 'chef', 'king') and exists (select 1 from public.inventories i where i.user_id = p.id)
  on conflict do nothing;

-- 4) the Gold back: what was bought in the shop or during an event (gifts cost nothing, grants were free)
with paid as (
  select v.user_id, sum(r.price::bigint * v.quantity) as amount
  from public.inventory_items v join retired_items r on r.item_id = v.item_id
  where r.price > 0 and v.source in ('shop', 'event')
  group by v.user_id
), credited as (
  update public.wallets w set gold = w.gold + p.amount, updated_at = now()
  from paid p where w.user_id = p.user_id
  returning w.user_id, w.gold, p.amount
)
insert into public.transactions (user_id, currency_id, amount, balance_after, kind, description, ref)
select user_id, 'gold', amount, gold, 'refund', 'Devolução: itens retirados da loja', jsonb_build_object('migration', 'hacker_collection')
from credited;

-- 5) the retired items leave every inventory (their equipped rows go with them: FK on delete cascade)
delete from public.inventory_items v using retired_items r where v.item_id = r.item_id;

-- 6) the first new skin, given and equipped
insert into public.inventory_items (user_id, item_id, quantity, source)
  select s.user_id, 'hx_hoodie', 1, 'compensation' from skin_swap s
  on conflict (user_id, item_id) do nothing;
insert into public.transactions (user_id, item_id, amount, kind, description, ref)
  select s.user_id, 'hx_hoodie', 1, 'grant', 'Skin nova no lugar de uma retirada da loja', jsonb_build_object('migration', 'hacker_collection')
  from skin_swap s;
insert into public.equipped_items (user_id, slot, item_id, inventory_item_id)
  select v.user_id, 'shirt', v.item_id, v.id from public.inventory_items v join skin_swap s on s.user_id = v.user_id where v.item_id = 'hx_hoodie'
  on conflict (user_id, slot) do update set item_id = excluded.item_id, inventory_item_id = excluded.inventory_item_id, equipped_at = now();
update public.profiles p set avatar = (case when jsonb_typeof(p.avatar) = 'object' then p.avatar else '{}'::jsonb end) || '{"outfit": "hx_hoodie"}'::jsonb
  where p.id in (select user_id from skin_swap);

-- 7) every other avatar checked again against what the player owns now: private.sanitize_avatar puts
-- retired hats, hairstyles, pants and accessories back to the free default
update public.profiles set avatar = avatar where avatar is not null and avatar <> '{}'::jsonb and id not in (select user_id from skin_swap);

-- 8) out of the shop for good
update public.items set active = false, purchasable = false where id in (select item_id from retired_items);

commit;
